/**
 * AWX Plugin for OpenCode
 *
 * Provides native tool access to AWX / Ansible Automation Platform
 * for job templates, projects, and job lifecycle operations.
 *
 * ## Plugin Lifecycle
 *
 * 1. On load, the plugin registers its auth hook (type: "api" bearer token).
 * 2. If a PAT was previously stored, init-time validation calls GET /api/v2/me/
 *    to verify the token is still active.
 * 3. Tools consume the validated token for all AWX API requests.
 *
 * ## Configuration
 *
 * The plugin reads `baseUrl` from the `AWX_BASE_URL` environment variable:
 * ```bash
 * export AWX_BASE_URL="https://example.com"
 * ```
 * The plugin is registered as a string-only entry in opencode.jsonc:
 * ```jsonc
 * { "plugin": ["@weiyentan/opencode-plugin-awx"] }
 * ```
 */
import type { PluginInput, Hooks, Plugin } from "@opencode-ai/plugin";

import { createAwxAuthHook, validateToken } from "./auth.js";
import { MetricsStore, setupMetricsPersistence } from "./metrics.js";
import { createClient, createTimeoutSignal } from "./client.js";
import type { AwxClient } from "./client.js";

import { getCustomConfig } from "./runtime-config.js";

// Tool factory imports
import { createHelloTool } from "./tools/hello.js";
import { createConfigTools } from "./tools/configure.js";
import { createAttachCredentialTool } from "./tools/attach-credential.js";
import { createDetachCredentialTool } from "./tools/detach-credential.js";
import { createSyncProjectTool } from "./tools/sync-project.js";
import { createJobEventsTool } from "./tools/job-events.js";
import { createGetResourceTool } from "./tools/get-resource.js";
import { createListTools } from "./tools/list.js";
import { createJobLifecycleTools } from "./tools/job-lifecycle.js";
import { createCrudTools } from "./tools/crud.js";
import { createRunCommandTool } from "./tools/run-command.js";
import { createLaunchWorkflowTool } from "./tools/launch-workflow.js";
import { createPingTool } from "./tools/ping.js";


/**
 * Plugin server function — the single entry point.
 *
 * Receives PluginInput (client, project, directory, worktree, serverUrl, $)
 * and returns Hooks. No plugin options are accepted — all configuration
 * comes from environment variables:
 * - `AWX_BASE_URL`: Base URL of the AAP/AWX instance (required)
 *
 * Returns Hooks including:
 * - Auth hook (type: "api" for bearer token / PAT)
 * - Registered tools (awx-list-templates, awx-launch-job, awx-job-status, etc.)
 */
async function server(input: PluginInput): Promise<Hooks> {
  const { serverUrl } = input;
  const baseUrl = process.env.AWX_BASE_URL;

  /* ── Auth hook ────────────────────────────────────────────── */
  const authHook = createAwxAuthHook();

  /* ── Metrics lifecycle ────────────────────────────────────── */
  // Create the shared MetricsStore early, before the AWX client,
  // so the middleware pipeline can record metrics through it.
  // Restore persisted counters from disk and set up periodic persistence
  // so that in-memory counters survive plugin reloads. The dispose hook
  // (returned via Hooks.dispose) will stop the interval and flush counters.
  const metricsStore = new MetricsStore();
  try {
    await metricsStore.load();
  } catch {
    // load failures (e.g. corrupt file) are non-fatal — counters start fresh
    void input.client.app.log({
      body: {
        service: "plugin-awx",
        level: "error",
        message: "Failed to load persisted metrics; starting fresh",
      },
    });
  }

  const persistence = setupMetricsPersistence(metricsStore, 30_000, (err) => {
    try {
      input.client.app?.log?.({
        body: {
          service: "plugin-awx",
          level: "error",
          message: `Metrics persistence failed: ${err instanceof Error ? err.message : String(err)}`,
        },
      });
    } catch {
      // Swallow logging errors (e.g. during dispose after test teardown)
    }
  });

  /* ── AWX HTTP client — lazy resolver, created on first tool call ── */
  let cachedClient: AwxClient | undefined;
  let cachedToken: string | undefined;
  let cachedBaseUrl: string | undefined;

  async function getAwxClient(): Promise<AwxClient> {
    const resolvedBaseUrl = getCustomConfig()?.baseUrl ?? (process.env.AWX_BASE_URL || undefined);
    if (!resolvedBaseUrl) throw new Error("AWX_BASE_URL not configured. Set the AWX_BASE_URL environment variable to point to your AAP/AWX instance.");

    const token = getCustomConfig()?.token
      ?? await (input.client as any).getSecret?.("awx")
      ?? process.env.AWX_TOKEN;
    if (!token) throw new Error("AWX Personal Access Token (PAT) not configured. Store your PAT via the plugin auth prompt.");

    const tokenString = String(token);

    if (!cachedClient || cachedToken !== tokenString || cachedBaseUrl !== resolvedBaseUrl) {
      cachedToken = tokenString;
      cachedBaseUrl = resolvedBaseUrl;
      cachedClient = createClient(resolvedBaseUrl, tokenString, { metricsStore });
    }

    return cachedClient;
  }

  /* ── Init-time validation ─────────────────────────────────── */
  // If a baseUrl is configured, attempt to validate the connection.
  // Token validation depends on whether the user has already stored a PAT.
  // If no baseUrl is configured, skip — the user will configure it later.
  if (baseUrl) {
    try {
      const storedKey = getCustomConfig()?.token ?? await (input.client as any).getSecret?.("awx") ?? process.env.AWX_TOKEN;
      if (storedKey) {
        const { signal, clear } = createTimeoutSignal(10_000);

        try {
          const result = await validateToken(
            baseUrl,
            String(storedKey),
            signal,
          );

          if (!result.valid) {
            void input.client.app.log({
              body: {
                service: "plugin-awx",
                level: "error",
                message: `Init-time token validation failed: ${result.error}`,
              },
            });
          } else {
            void input.client.app.log({
              body: {
                service: "plugin-awx",
                level: "info",
                message: `Token validated successfully against ${baseUrl}`,
              },
            });
          }
        } finally {
          clear();
        }
      }
    } catch {
      void input.client.app.log({
        body: {
          service: "plugin-awx",
          level: "info",
          message: "No stored token found. Auth will be configured on first use.",
        },
      });
    }
  }

  /* ── Hooks ────────────────────────────────────────────────── */
  return {
    auth: authHook,
    dispose: async () => {
      await persistence.clear();
    },
    tool: {
      hello: createHelloTool(serverUrl),
      ...createConfigTools(),
      ...createCrudTools(getAwxClient),
      ...createJobLifecycleTools(getAwxClient),
      "awx-get-job-events": createJobEventsTool(getAwxClient),
      ...createListTools(getAwxClient, metricsStore),
      "awx-get-resource": createGetResourceTool(getAwxClient),
      "awx-sync-project": createSyncProjectTool(getAwxClient),
      "awx-attach-credential": createAttachCredentialTool(getAwxClient),
      "awx-detach-credential": createDetachCredentialTool(getAwxClient),
      "awx-run-command": createRunCommandTool(getAwxClient),
      ...createLaunchWorkflowTool(getAwxClient),
      "awx-ping": createPingTool(getAwxClient, baseUrl),
    },
  };
}

/**
 * AWX Plugin — the named async export consumed by the OpenCode plugin server.
 *
 * Registered in opencode.jsonc as a string-only plugin entry:
 * ```jsonc
 * { "plugin": ["@weiyentan/opencode-plugin-awx"] }
 * ```
 *
 * Configuration is read from environment variables:
 * - `AWX_BASE_URL`: Base URL of the AAP/AWX instance (e.g. "https://example.com")
 */
export const AwxPlugin: Plugin = server;
export default AwxPlugin;

/**
 * GitHub Plugin for OpenCode
 *
 * Provides native tool access to the GitHub API for issues, pull requests,
 * repositories, code search, user profiles, and browsing.
 *
 * ## Plugin Lifecycle
 *
 * 1. On load, the plugin registers its auth hook (type: "api" bearer token).
 * 2. If a PAT was previously stored, init-time validation calls GET /user
 *    to verify the token is still active.
 * 3. Tools consume the validated token for all GitHub API requests.
 *
 * ## Configuration
 *
 * The plugin reads its base URL and token from a 3-tier fallback chain:
 *   customConfig → getSecret → process.env.GITHUB_TOKEN
 *
 * The plugin is registered as a string-only entry in opencode.jsonc:
 * ```jsonc
 * { "plugin": ["@weiyentan/opencode-plugin-github"] }
 * ```
 */

import type { PluginInput, Hooks, Plugin } from "@opencode-ai/plugin";
import { tool } from "@opencode-ai/plugin";

import { createGitHubAuthHook, validateGitHubToken } from "./auth.js";
import { createGitHubClient, createTimeoutSignal } from "./client.js";
import type { GitHubClient } from "./client.js";
import { createGraphQLClient } from "./graphql.js";
import type { GitHubGraphQLClient } from "./graphql.js";
import { createRichTools } from "./tools/rich.js";
import { createQueryTool } from "./tools/query.js";
import { createIssueTools } from "./tools/issues.js";
import { createPrTools } from "./tools/prs.js";
import { createRepoTools } from "./tools/repos.js";
import { createCodeTools } from "./tools/code.js";
import { createUserTools } from "./tools/user.js";

const z = tool.schema;

/* ── Runtime configuration storage ──────────────────────────────── */

let customConfig: { baseUrl?: string; token?: string } | undefined;

function getCustomConfig(): { baseUrl?: string; token?: string } | undefined {
  return customConfig;
}

function setCustomConfig(config: { baseUrl?: string; token?: string } | undefined): void {
  customConfig = config;
}

/* ── Plugin server function ─────────────────────────────────────── */

/**
 * Plugin server function — the single entry point.
 *
 * Receives PluginInput (client, project, directory, worktree, serverUrl, $)
 * and returns Hooks. No plugin options are accepted — all configuration
 * comes from environment variables or tool arguments:
 * - `GITHUB_TOKEN`: GitHub Personal Access Token (PAT) (optional, env var fallback)
 * - `GITHUB_BASE_URL`: GitHub API base URL (optional, defaults to "https://api.github.com")
 *
 * Returns Hooks including:
 * - Auth hook (type: "api" for bearer token / PAT)
 * - Registered tools: hello, github-configure, github-debug-env,
 *   github_issue_get_full, github_pr_get_full, github_issue_search,
 *   github_repo_get_full, github_query,
 *   github_pr_list, github_pr_get, github_pr_create, github_pr_merge,
 *   github_repo_get, github_repo_search,
 *   github_code_search, github_user_get
 */
async function server(input: PluginInput): Promise<Hooks> {
  const { serverUrl } = input;

  /* ── Auth hook ────────────────────────────────────────────── */
  const authHook = createGitHubAuthHook();

  /* ── GitHub HTTP client — lazy resolver, created on first tool call ── */
  let cachedClient: GitHubClient | undefined;
  let cachedClientToken: string | undefined;
  let cachedClientBaseUrl: string | undefined;
  let cachedGraphQL: GitHubGraphQLClient | undefined;
  let cachedGraphQLToken: string | undefined;
  let cachedGraphQLBaseUrl: string | undefined;

  async function getGitHubClient(): Promise<GitHubClient> {
    const resolvedBaseUrl =
      getCustomConfig()?.baseUrl ??
      process.env.GITHUB_BASE_URL ??
      "https://api.github.com";

    // 3-tier fallback: customConfig → getSecret → env var
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const token =
      getCustomConfig()?.token ??
      await (input.client as any).getSecret?.("github") ??
      process.env.GITHUB_TOKEN;

    if (!token) {
      throw new Error(
        "GitHub Personal Access Token (PAT) not configured. " +
        "Store your PAT via the plugin auth prompt, the github-configure tool, " +
        "or the GITHUB_TOKEN environment variable.",
      );
    }

    const tokenString = String(token);

    if (!cachedClient || cachedClientToken !== tokenString || cachedClientBaseUrl !== resolvedBaseUrl) {
      cachedClientToken = tokenString;
      cachedClientBaseUrl = resolvedBaseUrl;
      cachedClient = createGitHubClient(resolvedBaseUrl, tokenString);
    }

    return cachedClient;
  }

  /** Lazy resolver for the GraphQL client, created on first rich-tool call */
  async function getGitHubGraphQL(): Promise<GitHubGraphQLClient> {
    const resolvedBaseUrl =
      getCustomConfig()?.baseUrl ??
      process.env.GITHUB_BASE_URL ??
      "https://api.github.com";

    // 3-tier fallback: customConfig → getSecret → env var
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const token =
      getCustomConfig()?.token ??
      await (input.client as any).getSecret?.("github") ??
      process.env.GITHUB_TOKEN;

    if (!token) {
      throw new Error(
        "GitHub Personal Access Token (PAT) not configured. " +
        "Store your PAT via the plugin auth prompt, the github-configure tool, " +
        "or the GITHUB_TOKEN environment variable.",
      );
    }

    const tokenString = String(token);

    if (!cachedGraphQL || cachedGraphQLToken !== tokenString || cachedGraphQLBaseUrl !== resolvedBaseUrl) {
      cachedGraphQLToken = tokenString;
      cachedGraphQLBaseUrl = resolvedBaseUrl;
      cachedGraphQL = createGraphQLClient(tokenString, { baseUrl: resolvedBaseUrl });
    }

    return cachedGraphQL;
  }

  /* ── Init-time validation ─────────────────────────────────── */
  // If a token is configured, attempt to validate the connection.
  // If no token is configured, skip — the user will configure it later.
  (async () => {
    try {
      const resolvedBaseUrl =
        getCustomConfig()?.baseUrl ??
        process.env.GITHUB_BASE_URL ??
        "https://api.github.com";
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const storedKey =
        getCustomConfig()?.token ??
        await (input.client as any).getSecret?.("github") ??
        process.env.GITHUB_TOKEN;

      if (storedKey) {
        const { signal, clear } = createTimeoutSignal(10_000);

        try {
          const result = await validateGitHubToken(
            resolvedBaseUrl,
            String(storedKey),
            signal,
          );

          if (!result.valid) {
            void input.client.app.log({
              body: {
                service: "plugin-github",
                level: "error",
                message: `Init-time token validation failed: ${result.error}`,
              },
            });
          } else {
            void input.client.app.log({
              body: {
                service: "plugin-github",
                level: "info",
                message: "Token validated successfully against GitHub API.",
              },
            });
          }
        } finally {
          clear();
        }
      }
    } catch {
      void input.client.app.log({
        body: {
          service: "plugin-github",
          level: "info",
          message: "No stored token found. Auth will be configured on first use.",
        },
      });
    }
  })();

  /* ── Tools ────────────────────────────────────────────────── */

  /** Hello-world tool (Phase 0 scaffolding tracer) */
  const hello = tool({
    description: [
      "Returns a hello world greeting. Sanity-check tool that verifies",
      "plugin load, tool registration, and hot-reload behavior on the",
      `GitHub plugin server (connected to ${serverUrl.href}).`,
    ].join(" "),
    args: {
      name: z
        .string()
        .optional()
        .describe("Name to greet. Defaults to 'world'."),
    },
    async execute(args, context) {
      if (context.abort?.aborted) {
        return { output: "Request was aborted." };
      }

      const name = args.name ?? "world";
      return { output: `Hello, ${name}! 👋` };
    },
  });

  /** Debug tool that returns current GitHub environment configuration. */
  const debugEnv = tool({
    description: "Debug tool that returns current GitHub environment configuration.",
    args: {},
    async execute(_args, context) {
      if (context.abort?.aborted) return { output: "Request was aborted." };
      const config = getCustomConfig();
      return {
        output: JSON.stringify({
          hasToken: Boolean(
            config?.token ?? process.env.GITHUB_TOKEN,
          ),
          baseUrl:
            config?.baseUrl ??
            process.env.GITHUB_BASE_URL ??
            "https://api.github.com (default)",
        }),
      };
    },
  });

  /** Configure tool for setting GitHub connection settings. */
  const configure = tool({
    description: "Configure GitHub connection settings (base URL and/or PAT token).",
    args: {
      baseUrl: z
        .string()
        .optional()
        .describe("GitHub API base URL (e.g., https://api.github.com)"),
      token: z
        .string()
        .optional()
        .describe("GitHub Personal Access Token (PAT)"),
    },
    async execute(args, context) {
      if (context.abort?.aborted) {
        return { output: "Request was aborted." };
      }

      if (!args.baseUrl && !args.token) {
        return { output: "Provide at least one of: baseUrl, token" };
      }

      // Merge with existing config so partial updates don't clear previously set values
      const merged: { baseUrl?: string; token?: string } = {
        ...(getCustomConfig() ?? {}),
        ...(args.baseUrl ? { baseUrl: args.baseUrl } : {}),
        ...(args.token ? { token: args.token } : {}),
      };
      setCustomConfig(Object.keys(merged).length > 0 ? merged : undefined);

      // Invalidate cached clients so they re-resolve with new config
      cachedClient = undefined;
      cachedClientToken = undefined;
      cachedClientBaseUrl = undefined;
      cachedGraphQL = undefined;
      cachedGraphQLToken = undefined;
      cachedGraphQLBaseUrl = undefined;

      // Validate the client resolves with the new config
      let validationMessage = "";
      try {
        await getGitHubClient();
        validationMessage = " Client validated successfully.";
      } catch {
        validationMessage = " (client not validated — store a token and baseUrl to enable API calls)";
      }

      if (args.baseUrl && args.token) {
        return { output: `GitHub client configured and ready.${validationMessage}` };
      }

      return { output: `Configuration stored.${validationMessage}` };
    },
  });

  /* ── GraphQL-powered rich tools ──────────────────────────── */
  const richTools = createRichTools(getGitHubGraphQL);
  const queryTool = createQueryTool(getGitHubGraphQL);

  /* ── REST-powered issue tools ────────────────────────────── */
  const issueTools = createIssueTools(getGitHubClient);
  /* ── REST-powered PR, repo, code & user tools ───────────── */
  const prTools = createPrTools(getGitHubClient);
  const repoTools = createRepoTools(getGitHubClient);
  const codeTools = createCodeTools(getGitHubClient);
  const userTools = createUserTools(getGitHubClient);

  /* ── Hooks ────────────────────────────────────────────────── */
  return {
    auth: authHook,
    tool: {
      hello,
      "github-debug-env": debugEnv,
      "github-configure": configure,
      ...richTools,
      "github_query": queryTool,
      ...issueTools,
      ...prTools,
      ...repoTools,
      ...codeTools,
      ...userTools,
    },
  };
}

/**
 * GitHub Plugin — the named async export consumed by the OpenCode plugin server.
 *
 * Registered in opencode.jsonc as a string-only plugin entry:
 * ```jsonc
